import fs from 'fs'
import { extname } from 'path'
import chalk from 'chalk'
import readdirp from 'readdirp'
import { SingleBar } from 'cli-progress'
import prettyBytes from 'pretty-bytes'
import jpegquality from 'jpegquality'
import prettyMilliseconds from 'pretty-ms-i18n'
import compressJpeg from './jpeg.js'
import compressPng from './png.js'
import compressGif from './gif.js'
import tinypng from './tinypng.js'

const CACHE = {}
async function compressDir(dir, options) {
  Object.assign(options, { log: false })
  const lsOptions = {
    fileFilter: (f) => {
      const ext = extname(f.basename).toLocaleLowerCase()
      switch (ext) {
        case '.png':
        case '.jpg':
        case '.jpeg':
        case '.gif':
          return true
      }
      return false
    },
    alwaysStat: true
  }

  let count = 0
  let files = await readdirp.promise(dir, lsOptions)
  let limitSize = parseFloat(options.limit)
  if (isNaN(limitSize)) {
    limitSize = 1
  }
  files = files.filter(({ stats: { size } }) => size > 1024 * limitSize)
  // console.log(files)
  if (files.length == 0) {
    console.log('压缩:', count)
    return 0
  }

  const progressBar = new SingleBar({
    format: '' + chalk.cyan('{bar}') + ' {percentage}% || {value}/{total} images',
    barCompleteChar: '\u2588',
    barIncompleteChar: '\u2591',
    hideCursor: true,
    barsize: 40
  })
  progressBar.start(files.length, 0)

  for (let i = 0; i < files.length; i++) {
    const { fullPath } = files[i]

    const ret = await compressImage(fullPath, options).catch((ex) => {
      console.log('\n' + chalk.yellow(ex))
    })

    if (ret) {
      if (ret.output.size < ret.input.size) {
        count++
        fs.copyFileSync(ret.output.file, ret.input.file)
      }
      fs.rmSync(ret.output.file)

      CACHE[fullPath] = ret
    }
    progressBar.increment()
  }
  progressBar.stop()

  const cacheArr = Object.values(CACHE)
  if (cacheArr.length == 0) {
    console.log('压缩:', count)
    return 0
  }

  const inputSize =
    cacheArr.length > 1
      ? cacheArr.reduce((prev, cur) => (isNaN(prev) ? prev.input.size : prev) + cur.input.size)
      : cacheArr[0].input.size
  const outputSize =
    cacheArr.length > 1
      ? cacheArr.reduce((prev, cur) => (isNaN(prev) ? prev.output.size : prev) + cur.output.size)
      : cacheArr[0].output.size
  const compressRatio = Math.round(((inputSize - outputSize) / inputSize) * 100)

  console.log(
    '压缩:',
    count,
    '压缩前:',
    chalk.green(prettyBytes(inputSize)),
    '压缩后:',
    chalk.green(prettyBytes(outputSize)),
    chalk.yellow(`-${compressRatio}%`)
  )

  return files.length
}

export default async function compressImage(path, options) {
  const startTime = Date.now()

  let compRet

  let isDir = false

  const stat = fs.statSync(path)
  if (stat.isDirectory()) {
    isDir = true
    await compressDir(path, Object.assign({}, options))
  } else {
    if (options.showQuality) {
      try {
        console.log(jpegquality(fs.readFileSync(path)))
      } catch (ex) {
        console.log(chalk.red(ex))
      }
      return
    }

    const compPng = options.png2jpeg ? compressJpeg : compressPng
    const ext = extname(path).toLocaleLowerCase()
    switch (ext) {
      case '.png':
        compRet = await compPng(path, options)
        break
      case '.jpg':
      case '.jpeg':
        compRet = await compressJpeg(path, options)
        break
      case '.gif':
        compRet = await compressGif(path, options)
        break
      default:
        var UN_SUPPORT = 'Error: Unsupported image extension'
        compRet = Promise.reject(new Error(UN_SUPPORT))
        break
    }

    if (options.tinyPng) {
      await tinypng(path, options)
    }
  }

  options.log !== false &&
    console.log(
      `${isDir ? '共计' : ''}用时 ${chalk.hex('#0CCE6A')(
        prettyMilliseconds(Date.now() - startTime, { locale: 'zh_CN' })
      )}`
    )

  return compRet
}

