import jpegtranBin from 'jpegtran-bin'
import { execFile } from 'child_process'
import fs from 'fs'
import path from 'path'
import chalk from 'chalk'
import prettyBytes from 'pretty-bytes'
import jpegquality from 'jpegquality'
import imageSize from 'image-size'
import Exif from 'exif'
import getImageDiff from './image-diff.js'

async function cjpeg(filename, quality = 60, smooth = 10, outfile = '') {
  // console.log(quality, smooth)

  const defaultArgs = ['-smooth', smooth, '-quant-table', 0]
  defaultArgs.push(...['-optimize', '-progressive'])
  const qualityArg = ['-quality', quality]

  if (outfile) {
    defaultArgs.push('-outfile', outfile)
  }

  return new Promise((resolve, reject) => {
    execFile(
      mozjpeg,
      [...defaultArgs, ...qualityArg, filename],
      { encoding: 'buffer', maxBuffer: 10 * 1024 * 1024 },
      (err, stdout, stderr) => {
        stderr = stderr.toString()
        if (stderr && !stderr.includes('Premature end of JPEG file')) {
          if (stderr.includes('Smoothing not supported')) {
            return resolve(stdout)
            /** Smoothing报错，但不影响生成 */
            // console.log(
            //   '\n' + filename,
            //   '\nquality:',
            //   quality,
            //   'smooth:',
            //   smooth,
            //   chalk.red(stderr)
            // )
            // return cjpeg(filename, quality, 0, outfile).then(resolve).catch(reject)
          }

          return reject(new Error(stderr))
        }

        resolve(stdout)
      }
    )
  })
}

async function jpegtran(filename, exifOrientation) {
  const defaultArgs = ['-copy', 'none', '-trim']

  switch (exifOrientation) {
    case 1:
      break
    case 2:
      defaultArgs.push('-flip', 'horizontal')
      break
    case 3:
      defaultArgs.push('-rotate', 180)
      break
    case 4:
      defaultArgs.push('-flip', 'vertical')
      break
    case 5:
      defaultArgs.push('-rotate', 90)
      defaultArgs.push('-flip', 'horizontal')
      break
    case 6:
      defaultArgs.push('-rotate', 90)
      break
    case 7:
      defaultArgs.push('-rotate', 90)
      defaultArgs.push('-flip', 'vertical')
      break
    case 8:
      defaultArgs.push('-rotate', 270)
      break
  }

  defaultArgs.push('-outfile', filename)

  return new Promise((resolve, reject) => {
    execFile(
      jpegtranBin,
      [...defaultArgs, filename],
      { encoding: 'buffer', maxBuffer: 10 * 1024 * 1024 },
      (err, stdout, stderr) => {
        stderr = stderr.toString()
        if (stderr) {
          return reject(new Error(stderr))
        }

        resolve(stdout)
      }
    )
  })
}

async function getExif(path) {
  return new Promise((resolve, reject) => {
    Exif(path, (err, exif) => {
      if (err) {
        reject(err)
      } else {
        resolve(exif)
      }
    })
  })
}

function getSmooth(imgSize) {
  const wh = imgSize.width * imgSize.height
  let smooth = 5
  if (wh > 1920 * 1080) {
    smooth = 10
  }
  if (wh >= 2560 * 1440) {
    smooth = 15
  }
  if (wh >= 3840 * 2160) {
    smooth = 20
  }
  if (wh >= 5120 * 2880) {
    smooth = 25
  }
  return smooth
}
function getQintFn(imgSize) {
  const wh = imgSize.width * imgSize.height
  let intFn = Math.ceil
  if (wh >= 1920 * 1080) {
    intFn = Math.round
  }
  if (wh >= 3840 * 2160) {
    intFn = Math.floor
  }
  return intFn
}

async function compJPEG(filename, quality, smooth, log = true, ssimLimit = 0.99801) {
  const imgBuf = fs.readFileSync(filename)
  const imgSize = imageSize(imgBuf)

  let oriQ = 100 // png quality think 100
  try {
    oriQ = Math.round(jpegquality(imgBuf))
  } catch {}

  const [minQ, maxQ] = [Math.min(oriQ, 60), Math.min(90, oriQ)]

  let _quality = quality ?? minQ
  smooth = smooth ?? getSmooth(imgSize)

  let outfileName = `${path.parse(filename).name}-${_quality}.jpg`
  let outfile = path.join(path.dirname(filename), outfileName)

  await cjpeg(filename, _quality, smooth, outfile)
  const ssimQ1 = await imageDiffFn(filename, outfile)
  let mssim = ssimQ1

  if (quality == undefined && ssimQ1 < ssimLimit) {
    await cjpeg(filename, maxQ, smooth, outfile)
    const ssimQ2 = await imageDiffFn(filename, outfile)
    fs.rmSync(outfile)

    // 大图片，quality取向偏低
    const intFn = getQintFn(imgSize)
    let qAdd = 0
    if (maxQ > minQ) {
      qAdd = (ssimLimit - ssimQ1) / ((ssimQ2 - ssimQ1) / (maxQ - minQ))
      qAdd = intFn(qAdd)
    }
    // console.log(_quality, ssimQ1, ssimQ2, qAdd, intFn, [minQ, maxQ])
    _quality = Math.min(minQ + qAdd, maxQ, oriQ)
    outfileName = `${path.parse(filename).name}-${_quality}.jpg`
    outfile = path.join(path.dirname(filename), outfileName)

    await cjpeg(filename, _quality, smooth, outfile)
    mssim = await imageDiffFn(filename, outfile)
  }

  const exif = await getExif(filename).catch(() => {})
  await jpegtran(outfile, exif?.image?.Orientation)

  const oriSize = fs.statSync(filename).size
  const compSize = fs.statSync(outfile).size
  const compRatio = ((compSize / oriSize) * 100).toFixed(1) + '%'

  log &&
    console.log(
      chalk.green(outfileName),
      '     大小:',
      chalk.yellow(prettyBytes(oriSize, { binary: true })),
      '->',
      chalk.yellow(prettyBytes(compSize, { binary: true })),
      '\t品质:',
      oriQ,
      '->',
      chalk.yellow(`${_quality}`), //(${smooth})
      '\t压缩率:',
      chalk.yellow(compRatio),
      '\t相似度:',
      mssim
    )

  return {
    // buffer,
    // file: outfile,
    quality: _quality,
    compRatio,
    mssim,
    contentType: 'image/jpeg',
    input: { size: oriSize, file: filename },
    output: { size: compSize, file: outfile }
  }
}

let imageDiffFn
export default async function compressJpeg(path, options) {
  // console.log(options)

  imageDiffFn = getImageDiff(options.diff)
  return await compJPEG(path, options.quality, options.smooth, options.log)
}

