import fs from 'fs'
import path from 'path'
import chalk from 'chalk'
import syncRequest from 'sync-request'
import jpegquality from 'jpegquality'
import prettyBytes from 'pretty-bytes'
import getImageDiff from './image-diff.js'

export async function tinypng(filename) {
  let req, res, oriBuffer

  try {
    oriBuffer = fs.readFileSync(filename)
  } catch (ex) {
    console.log(chalk.red(ex))
    return false
  }

  try {
    req = syncRequest('POST', 'https://tinypng.com/web/shrink', {
      headers: {
